function mergeLines(a, b, opts){
  opts=opts||{}; var sep=opts.sep!=null?opts.sep:'\t';
  var A=String(a||'').split(/\r?\n/), B=String(b||'').split(/\r?\n/);
  var n=Math.max(A.length,B.length); var out=[];
  for(var i=0;i<n;i++) out.push((A[i]||'')+sep+(B[i]||''));
  return {ok:true, text:out.join('\n'), rows:n};
}

var EXPORTS={mergeLines:mergeLines};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MergeForgePure = EXPORTS; }
